    def test_navigation_warmup_does_not_launch_hidden_workspace_pages(self):
        instant = (ROOT / "upos" / "static" / "instant-navigation.js").read_text(
            encoding="utf-8"
        )
        warmup = (ROOT / "upos" / "static" / "app-warmup.js").read_text(
            encoding="utf-8"
        )

        self.assertNotIn("requestPrerenderBatch", instant)
        self.assertNotIn("speculationrules", instant)
        self.assertNotIn("requestPrerender", instant)
        self.assertNotIn("prerenderAll", warmup)
        self.assertIn("workspaceWarmup?.warm", instant)
        self.assertIn('"X-UPOS-Prefetch": "1"', instant)
        self.assertIn('document.addEventListener("pointerover"', instant)
        self.assertIn('document.addEventListener("focusin"', instant)
        self.assertIn('document.addEventListener("pointerdown"', instant)
        self.assertIn("requestWarm(destination(target))", instant)

    def test_background_pollers_wait_for_prerender_activation(self):
        notifications = (
            ROOT / "upos" / "static" / "messenger-notifications.js"
        ).read_text(encoding="utf-8")
        heartbeat = (ROOT / "upos" / "static" / "device-heartbeat.js").read_text(
            encoding="utf-8"
        )

        self.assertIn("document.prerendering", notifications)
        self.assertIn('"prerenderingchange"', notifications)
        self.assertIn("document.prerendering", heartbeat)
        self.assertIn('"prerenderingchange"', heartbeat)

    def test_messenger_notifications_poll_only_from_the_foreground_tab(self):
        notifications = (
            ROOT / "upos" / "static" / "messenger-notifications.js"
        ).read_text(encoding="utf-8")

        self.assertIn("function isForegroundTab()", notifications)
        self.assertIn('document.visibilityState !== "hidden"', notifications)
        self.assertIn("document.hasFocus()", notifications)
        self.assertIn("if (!isForegroundTab())", notifications)
        self.assertIn('window.addEventListener("focus"', notifications)
        self.assertIn("if (refreshPromise) return refreshPromise", notifications)
        self.assertIn("MIN_REQUEST_GAP_MS", notifications)
        self.assertIn("scheduleResumeRefresh", notifications)

